resources.string:
// Globals persist between SystemUI calls but may be cleared at any time.
var calls = 0;

function run(ctx) {
  var input = ctx.input || {};
  if (typeof input.text !== 'string') return null;  // Keep the original text.
  calls++;
  return input.text + ' ' + oshin.fmtDate(ctx.now, 'E');
}
